 import { supabase } from '../lib/supabase'

/**
 * Upload an image to Supabase Storage
 * @param {File} file - The image file to upload
 * @param {string} userId - The user ID for folder organization
 * @param {string} bucket - The storage bucket name (default: 'post-images')
 * @returns {Promise<string>} - The public URL of the uploaded image
 */
export async function uploadImage(file, userId, bucket = 'post-images') {
    if (!file) return null
    
    // Validate file type
    if (!file.type.startsWith('image/')) {
        throw new Error('File must be an image')
    }
    
    // Validate file size (max 5MB)
    if (file.size > 5 * 1024 * 1024) {
        throw new Error('Image must be less than 5MB')
    }
    
    const fileExt = file.name.split('.').pop()
    const fileName = `${userId}/${Date.now()}-${Math.random().toString(36).substring(2, 8)}.${fileExt}`
    
    const { error } = await supabase.storage
        .from(bucket)
        .upload(fileName, file, {
            cacheControl: '3600',
            upsert: false,
            contentType: file.type
        })
    
    if (error) {
        console.error('Upload error:', error)
        throw new Error('Failed to upload image: ' + error.message)
    }
    
    const { data } = supabase.storage
        .from(bucket)
        .getPublicUrl(fileName)
    
    return data.publicUrl
}

/**
 * Delete an image from Supabase Storage
 * @param {string} filePath - The full file path in storage
 * @param {string} bucket - The storage bucket name (default: 'post-images')
 */
export async function deleteImage(filePath, bucket = 'post-images') {
    if (!filePath) return
    
    try {
        // Extract the path from the full URL if needed
        const url = new URL(filePath)
        const path = url.pathname.split('/').slice(3).join('/')
        
        const { error } = await supabase.storage
            .from(bucket)
            .remove([path])
        
        if (error) {
            console.error('Delete error:', error)
        }
    } catch (error) {
        console.error('Error deleting image:', error)
    }
}

/**
 * Upload a profile avatar
 * @param {File} file - The image file to upload
 * @param {string} userId - The user ID
 * @returns {Promise<string>} - The public URL of the uploaded avatar
 */
export async function uploadAvatar(file, userId) {
    return uploadImage(file, userId, 'avatars')
}
